testo:
{
 "genere": "prevedi",
 "titolo": "Prevedi il risultato - Collaudo",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> int:
	var severities: Array[String] = ["low", "high", "medium", "high", "low"]
	var high_count: int = 0
	for s in severities:
		if s == "high":
			high_count += 1
	return high_count
",
   "domanda": "Quanti bug con gravità "high" vengono contati?",
   "spiegazione": "Il ciclo scorre l'array `severities` e incrementa `high_count` ogni volta che trova la stringa "high". Nell'array ce ne sono esattamente 2."
  },
  {
   "codice": "extends RefCounted


func run() -> bool:
	var steps: Array[String] = ["apri il menu", "clicca opzioni", "premi audio"]
	return steps.has("clicca opzioni") and steps.size() >= 3
",
   "domanda": "Cosa restituisce `run()`?",
   "spiegazione": "`steps.has("clicca opzioni")` è vero perché la stringa è presente nell'array. Anche `steps.size() >= 3` è vero perché l'array contiene 3 elementi. Entrambe le condizioni in `and` sono vere, quindi restituisce `true`."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var is_crash: bool = true
	var is_frequent: bool = false
	if is_crash and is_frequent:
		return "blocca tutto"
	elif is_crash:
		return "correggi subito"
	else:
		return "rimanda"
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`is_crash and is_frequent` è falso perché `is_frequent` è falso. Si passa al primo `elif`, dove `is_crash` è vero: la funzione restituisce "correggi subito" e si ferma."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var logs: Array[String] = ["ERRORE: file mancante", "OK: caricato", "ERRORE: salvataggio fallito"]
	var errors: Array[String] = []
	for log in logs:
		if log.begins_with("ERRORE"):
			errors.append(log)
	return errors.size()
",
   "domanda": "Quanti elementi contiene l'array `errors` alla fine?",
   "spiegazione": "Il ciclo controlla ogni stringa: quelle che iniziano con "ERRORE" vengono aggiunte all'array `errors`. Ce ne sono 2 ("ERRORE: file mancante" e "ERRORE: salvataggio fallito"), quindi la dimensione finale è 2."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var fixed_bugs: Array[int] = [12, 15, 18]
	fixed_bugs.append(22)
	fixed_bugs.remove_at(0)
	return str(fixed_bugs.size())
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "L'array parte con 3 elementi. Con `append(22)` sale a 4 elementi. Con `remove_at(0)` viene rimosso il primo elemento all'indice 0 (il numero 12), lasciando di nuovo 3 elementi. La funzione restituisce la stringa "3"."
  }
 ]
}
